async def test_deletion_is_durable_idempotent_and_removes_generated_files(fixture):
    f = fixture
    async with f.db() as db:
        accepted = await service.request_deletion(db, "chat", f.user)
    async with f.db() as db:
        repeated = await service.request_deletion(db, "chat", f.user)
        assert repeated["cleanup_task_id"] == accepted["cleanup_task_id"]
        row = await db.scalar(select(AutoResearchSession))
        assert row.status == "stopping" and row.recovery_metadata["delete_requested"]
    assert all(path.exists() for path in f.paths)
    await service.cleanup_records_and_files(accepted["cleanup_task_id"])
    # Object cleanup hands owned bytes to a durable, reference-aware file outbox.
    async with f.db() as db:
        cleanup = await db.scalar(select(StorageTask).where(StorageTask.task_type == 'file_cleanup'))
        assert cleanup and cleanup.status == 'pending'
        assert str(f.root) in cleanup.params['paths']
    assert f.input_file.read_text() == "source data"
    async with f.db() as db:
        for cls in [
            ChatConversation,
            ChatMessage,
            AutoResearchSession,
            ResearchJob,
            TrainingTask,
            TrainedModel,
            Manuscript,
        ]:
            assert (await db.scalars(select(cls))).all() == []
        assert await db.scalar(select(Dataset.dataset_id)) == "data"
        assert await db.scalar(select(WorkbenchFile)) is None
        assert await db.scalar(select(StorageTask.status).where(StorageTask.task_type == 'chat_delete')) == "completed"
        assert (await service.request_deletion(db, "chat", f.user))["status"] == "deleted"


async def test_delete_acknowledges_before_slow_process_shutdown_or_file_cleanup(
    fixture, monkeypatch
):
    from gateway.routes.chat_conversation import delete_conversation
    from backend.database.repositories import ChatRepository

    f = fixture
    entered, release = asyncio.Event(), asyncio.Event()

    async def slow_stop(rows):
        entered.set()
        await release.wait()

    monkeypatch.setattr(service, "cancel_immediately", slow_stop)
    monkeypatch.setattr(service, "schedule_cancellation", schedule_cancellation)
    cleanup = AsyncMock(side_effect=AssertionError("Request must not delete files"))
    monkeypatch.setattr(
        "gateway.routes.chat_patch_inference.cleanup_conversation_chat_patch_tasks", cleanup
    )
    try:
        async with f.db() as db:
            result = await asyncio.wait_for(delete_conversation("chat", f.user, db), .5)
        assert result == {"conversation_id": "chat", "status": "deleted"}
        await asyncio.wait_for(entered.wait(), 1)
        assert all(path.exists() for path in f.paths)
        async with f.db() as db:
            assert await ChatRepository.get_user_conversations(db, "owner") == []
            assert (await db.get(WorkbenchFile, "upload")).deleted
        cleanup.assert_not_called()
    finally:
        release.set()
        await asyncio.gather(*list(service._cancellations.values()))


async def test_internal_cleanup_does_not_displace_visible_storage_tasks_or_expire(fixture):
    from datetime import timedelta
    from backend.database.models import utc_now
    from backend.database.repositories.storage_task import StorageTaskRepository

    async with fixture.db() as db:
        await service.request_deletion(db, "chat", fixture.user)
        db.add(StorageTask(
            task_id="visible", user_id="owner", task_type="batch_import",
            status="processing", created_at=utc_now() - timedelta(hours=1),
        ))
        await db.commit()
        visible = await StorageTaskRepository.get_user_tasks(db, "owner", limit=1)
        assert [row.task_id for row in visible] == ["visible"]
        internal = await db.scalar(
            select(StorageTask).where(StorageTask.task_type == "chat_delete")
        )
        internal.status = "failed"
        internal.completed_at = utc_now() - timedelta(days=30)
        await db.commit()
        await StorageTaskRepository.cleanup_old_tasks(db)
        assert await db.scalar(
            select(StorageTask).where(StorageTask.task_id == internal.task_id)
        ) is not None


async def test_cleanup_removes_owned_versions_but_preserves_referenced_files(
    fixture, monkeypatch
):
    from backend.services import file_library, knowledge

    f = fixture
    saved, revision = file_library.store_bytes(
        "owner", "shared", "shared.txt", b"independent reference"
    )
    original, _ = file_library.store_bytes(
        "owner", "upload", "input.txt", b"old version"
    )
    updated, _ = file_library.store_bytes(
        "owner", "upload", "input.txt", b"new version"
    )
    removed = []
    monkeypatch.setattr(
        knowledge, "remove_index", lambda owner, identity: removed.append(identity)
    )
    async with f.db() as db:
        db.add(
            WorkbenchFile(
                file_id="shared",
                user_id="owner",
                name="shared.txt",
                path=saved,
                storage_path=saved,
                revision=revision,
            )
        )
        message = await db.scalar(select(ChatMessage))
        message.extra_metadata = {
            "resource_references": [{"kind": "file", "id": "shared"}]
        }
        await db.flush()
        db.add(
            MessageFeedback(
                message_id=message.id, user_id="owner", feedback_type="thumbs_up"
            )
        )
        db.add(
            ResultSource(
                source_id="source",
                user_id="owner",
                task_id="run",
                session_id="r",
                kind="experiment",
                title="Run",
                task_type="patch_classification",
                revision="r",
            )
        )
        await db.flush()
        db.add(ResultSourceDataset(source_id="source", dataset_id="data"))
        await db.commit()
        accepted = await service.request_deletion(db, "chat", f.user)
        assert (await db.get(WorkbenchFile, "upload")).deleted
        assert not (await db.get(WorkbenchFile, "shared")).deleted
    await service.cleanup_records_and_files(accepted["cleanup_task_id"])
    from pathlib import Path

    assert Path(saved).read_bytes() == b"independent reference"
    assert not Path(original).exists() and not Path(updated).exists()
    assert removed == ["upload"]
    async with f.db() as db:
        assert await db.get(WorkbenchFile, "shared")
        for model in [ResultSource, ResultSourceDataset, MessageFeedback]:
            assert not (await db.scalars(select(model))).all()


async def test_running_jobs_block_file_removal_until_cancellation(fixture):
    f = fixture
    async with f.db() as db:
        job = await db.get(ResearchJob, "run")
        job.status = "running"
        await db.commit()
        accepted = await service.request_deletion(db, "chat", f.user)
    with pytest.raises(RuntimeError, match="cancellation"):
        await service.cleanup_records_and_files(accepted["cleanup_task_id"])
    assert all(path.exists() for path in f.paths)


async def test_cleanup_failure_retains_manifest_for_retry(fixture, monkeypatch):
    f = fixture
    async with f.db() as db:
        accepted = await service.request_deletion(db, "chat", f.user)
    from backend.storage import deletion
    original = deletion.enqueue
    monkeypatch.setattr(deletion,'enqueue',AsyncMock(side_effect=OSError('busy file')))
    with pytest.raises(OSError, match="busy file"):
        await service.cleanup_records_and_files(accepted["cleanup_task_id"])
    async with f.db() as db:
        task = await db.scalar(select(StorageTask))
        assert task.params["manifest"]["run_ids"] == ["run"]
        assert await db.scalar(select(ChatConversation.conversation_id)) == "chat"
    monkeypatch.setattr(deletion,'enqueue',original)
    await service.cleanup_records_and_files(accepted["cleanup_task_id"])
    async with f.db() as db:
        assert await db.scalar(select(StorageTask).where(StorageTask.task_type == 'file_cleanup'))


