async def test_worker_stops_agent_jobs_and_writer_before_cleanup(fixture, monkeypatch):
    f = fixture
    order = []

    async def running(label):
        try:
            await asyncio.Event().wait()
        finally:
            order.append(label)

    agent = asyncio.create_task(running("agent stopped"))
    writer = asyncio.create_task(running("writer stopped"))
    await asyncio.sleep(0)
    async with f.db() as db:
        accepted = await service.request_deletion(db, "chat", f.user)
    scheduler = SimpleNamespace(tasks={"r": agent})
    writing = SimpleNamespace(tasks={"report": writer})
    monkeypatch.setattr(
        "backend.autoresearch.engine.runtime.AgentRuntime.cleanup_orphan",
        AsyncMock(side_effect=lambda: order.append("orphan stopped")),
    )
    monkeypatch.setattr(
        "backend.autoresearch.engine.worker.stop_jobs",
        AsyncMock(side_effect=lambda sid: order.append("jobs stopped")),
    )
    monkeypatch.setattr(
        "backend.autoresearch.engine.store.jobs", AsyncMock(return_value=[])
    )
    cleanup = AsyncMock(side_effect=lambda identity: order.append("files deleted"))
    monkeypatch.setattr(service, "cleanup_records_and_files", cleanup)
    await service.ChatDeletionQueue(scheduler, writing).run(accepted["cleanup_task_id"])
    assert order == [
        "agent stopped",
        "orphan stopped",
        "jobs stopped",
        "writer stopped",
        "files deleted",
    ]
    assert not scheduler.tasks and not writing.tasks
